const BLACK_VIDEO = 'data:video/mp4;base64,';

export class ScreenAwake {
  #lock: WakeLockSentinel | null = null;
  #video: HTMLVideoElement | null = null;
  #held = false;

  hold(): void {
    if (this.#held) return;
    this.#held = true;
    this.#playVideo();
    void this.#requestLock();
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState !== 'visible') return;
      void this.#requestLock();
      void this.#video?.play().catch(() => undefined);
    });
  }

  async #requestLock(): Promise<void> {
    if (this.#lock !== null && !this.#lock.released) return;
    this.#lock = (await navigator.wakeLock?.request('screen').catch(() => null)) ?? null;
  }

  #playVideo(): void {
    const video = document.createElement('video');
    video.src = BLACK_VIDEO;
    video.muted = true;
    video.loop = true;
    video.playsInline = true;
    video.setAttribute('playsinline', '');
    video.setAttribute('aria-hidden', 'true');
    video.style.cssText = 'position:fixed;bottom:0;right:0;width:1px;height:1px;opacity:0.01;pointer-events:none';
    document.body.appendChild(video);
    void video.play().catch(() => undefined);
    this.#video = video;
  }
}
